contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        uint potBefore = c.pot();
        uint bankBalanceBefore = bank.balance; // direct read of bank's balance is not allowed; read via public getter
        // Actually bank is public address getter: c.bank()
        address bankAddr = c.bank();
        uint bankBalBefore = bankAddr.balance;

        bool reverted;
        try c.play{value: amount}() { reverted = false; } catch { reverted = true; }

        uint potAfter = c.pot();
        uint bankBalAfter = bankAddr.balance;

        // Rule: if the call succeeded and sent exactly 10 wei (TICKET_AMOUNT),
        // then either pot becomes 0 (payout) or pot becomes potBefore + 10 (no payout).
        // Additional distinguishing: if potAfter == 0 then the bank's balance must have increased by FEE_AMOUNT (1).
        // If potAfter == potBefore + 10, bank balance unchanged.
        // General rule covering all successful ticket-amount calls:
        if (!reverted) {
            // success implies amount == TICKET_AMOUNT (since only then no revert)
            assert(
                (potAfter == 0 && bankBalAfter == bankBalBefore + 1) ||
                (potAfter == potBefore + 10 && bankBalAfter == bankBalBefore)
            );
        } else {
            // revert: amount != TICKET_AMOUNT, pot unchanged
            assert(potAfter == potBefore);
        }
    }

    receive() external payable {}
}

